\title{A Prime-Power Criterion for the GCD of the Interior of a Pascal Row}
\author{Aristotle}
\date{June 27, 2026}

\begin{document}

\begin{abstract}
For an integer $k \ge 1$ let
\[
F(k) \;=\; \gcd_{1 \le i \le k} \bin{k+1}{i}
\]
be the greatest common divisor of the \emph{interior} entries of row $k+1$ of Pascal's triangle (the entries strictly between the two bounding $1$'s). We give a complete, self-contained account of the classical fact that $F(k)$ is a perfect detector of prime powers:
\[
F(k) = 1 \iff k+1 \text{ is not a prime power.}
\]
Moreover, when $k+1 = p^a$ is a prime power, $F(k) = p$. The forward half shows that if $k+1 = p^a$ then $p$ divides every interior binomial coefficient. The backward half is the substantive content: if $k+1$ is not a prime power, then for each prime $p \mid k+1$ the explicit interior index $i = p^{\vp(k+1)}$ gives $\bin{k+1}{i}$ coprime to $p$, via a carry-free base-$p$ addition (Kummer's theorem); hence the gcd is $1$. We present definitions, supporting lemmas with proof sketches, algorithms, numerical demonstrations, and generalizations to stretched binomial families.
\end{abstract}

\maketitle

\section{Introduction}

Pascal's triangle assigns to each row $n \ge 0$ the binomial coefficients $\bin{n}{0}, \dots, \bin{n}{n}$. The two end entries are always $1$; the \emph{interior} of row $n$ is the multiset $\{\bin{n}{i} : 1 \le i \le n-1\}$. A classical observation (Balak Ram, 1909) states that the gcd of the interior of row $n$ equals the prime $p$ when $n = p^a$ is a prime power and equals $1$ otherwise.

We adopt the shift $n = k+1$ so that the interior index ranges over $\{1, \dots, k\}$, and define $F(k) = \gcd_{1 \le i \le k}\bin{k+1}{i}$.

\begin{theorem}[Main]\label{thm:main}
For all $k \ge 1$, \; $F(k) = 1 \iff k+1$ is not a prime power.
\end{theorem}

\subsection{Notation}
We write $\bin{n}{i} = 0$ for $i > n$. A positive integer $N$ is a \emph{prime power} if $N = p^a$ with $p$ prime and $a \ge 1$; we write $\IsPrimePow(N)$. Note $1$ is not a prime power. We let $\vp(N)$ be the $p$-adic valuation, $\operatorname{ordProj}_p(N) = p^{\vp(N)}$ the $p$-part, and $\operatorname{ordCompl}_p(N) = N/p^{\vp(N)}$ the prime-to-$p$ part.

\section{Definitions}

\begin{definition}[Interior Pascal-row gcd]
For $k \in \NN$,
\[
F(k) \;=\; \gcd_{1 \le i \le k} \bin{k+1}{i}.
\]
For $k \ge 1$ the index set $\{1,\dots,k\}$ is the interior of row $n = k+1$.
\end{definition}

\begin{remark}
$F(0) = \gcd \emptyset = 0$, which is why the theorem requires $k \ge 1$. For $k \ge 1$, $F(k) \ge 1$.
\end{remark}

\section{Supporting Lemmas}

Throughout, $p$ is prime.

\begin{lemma}[Divisor of every term]\label{lem:dvd}
For $1 \le i \le k$, \; $F(k) \mid \bin{k+1}{i}$.
\end{lemma}
\begin{proof}
The gcd of a finite family divides each member.
\end{proof}

\begin{lemma}[Prime-power rows are uniformly stamped]\label{lem:stamp}
If $k+1 = p^a$ with $a \ge 1$, then $p \mid F(k)$.
\end{lemma}
\begin{proof}[Proof sketch]
It suffices that $p \mid \bin{p^a}{i}$ for $1 \le i \le p^a - 1$. From the absorption identity $i\bin{p^a}{i} = p^a\bin{p^a - 1}{i-1}$, the prime $p$ divides the right side to order $a \ge 1$; since $0 < i < p^a$ gives $\vp(i) < a$, comparing valuations forces $\vp\!\bigl(\bin{p^a}{i}\bigr) \ge 1$. Taking the gcd over all interior $i$ yields $p \mid F(k)$.
\end{proof}

\begin{lemma}[Prime-power rows have $F \ne 1$]\label{lem:ne1}
If $k+1$ is a prime power then $F(k) \ne 1$.
\end{lemma}
\begin{proof}
Write $k+1 = p^a$, $a \ge 1$. By Lemma~\ref{lem:stamp}, $p \mid F(k)$; if $F(k) = 1$ then $p \mid 1$, impossible.
\end{proof}

\begin{lemma}[Carry-free central split]\label{lem:kummer}
Let $p$ be prime, $a \in \NN$, $m \in \NN$ with $p \nmid m$. Then
\[
p \nmid \bin{p^a \cdot m}{\,p^a\,}.
\]
\end{lemma}
\begin{proof}[Proof sketch]
Induct on $a$ via Lucas' theorem $\bin{N}{K} \equiv \bin{N \bmod p}{K \bmod p}\bin{\lfloor N/p\rfloor}{\lfloor K/p\rfloor} \pmod p$.
For $a = 0$: $\bin{m}{1} = m$ and $p \nmid m$. For $a+1$: with $N = p\cdot(p^a m)$, $K = p\cdot p^a$, the low digits vanish ($\bin{0}{0} = 1$), so
$\bin{p^{a+1}m}{p^{a+1}} \equiv \bin{p^a m}{p^a} \pmod p$, which is nonzero by induction.
Equivalently: adding $p^a$ and $p^a(m-1)$ in base $p$ produces no carries because the digit $m \bmod p \ne 0$; by Kummer, the carry count equals $\vp\!\bigl(\bin{p^a m}{p^a}\bigr) = 0$.
\end{proof}

\section{Main Theorem and Proof}

\begin{theorem}[Backward direction]\label{thm:back}
If $k \ge 1$ and $k+1$ is not a prime power, then $F(k) = 1$.
\end{theorem}
\begin{proof}[Proof sketch]
Suppose $F(k) \ne 1$. Then some prime $p \mid F(k)$. By Lemma~\ref{lem:dvd} at $i=1$, $F(k) \mid \bin{k+1}{1} = k+1$, so $p \mid k+1$. Let $a = \vp(k+1) \ge 1$ and $q = (k+1)/p^a$, so $k+1 = p^a q$, $p \nmid q$. Since $k+1$ is not a prime power, $q \ge 2$ and $p^a < k+1$, hence $p^a \le k$ and $i := p^a \in \{1,\dots,k\}$. By Lemma~\ref{lem:dvd}, $p \mid \bin{k+1}{p^a} = \bin{p^a q}{p^a}$. But Lemma~\ref{lem:kummer} with $m = q$ gives $p \nmid \bin{p^a q}{p^a}$, a contradiction. Thus $F(k) = 1$.
\end{proof}

\begin{proof}[Proof of Theorem~\ref{thm:main}]
($\Rightarrow$) Contrapositive of Lemma~\ref{lem:ne1}. ($\Leftarrow$) Theorem~\ref{thm:back}.
\end{proof}

\begin{corollary}[Exact value on the prime fibre]
If $k+1 = p^a$, then $F(k) = p$.
\end{corollary}
\begin{proof}[Proof sketch]
$p \mid F(k)$ by Lemma~\ref{lem:stamp}, and $F(k) \mid \bin{p^a}{1} = p^a$, so $F(k) = p^b$, $b \ge 1$. Taking $i = p^{a-1}$, Kummer's count gives $\vp\!\bigl(\bin{p^a}{p^{a-1}}\bigr) = 1$, forcing $b \le 1$. Hence $F(k) = p$.
\end{proof}

\section{Algorithms}

\subsection{Direct interior gcd}
Compute row $k+1$ via $\bin{n}{i} = \bin{n}{i-1}\cdot \frac{n-i+1}{i}$ and fold with $\gcd$. Cost: $O(k)$ exact big-integer operations.

\subsection{Prime-power detection via the criterion}
By Theorem~\ref{thm:main}, $F(k) = 1$ iff $k+1$ is not a prime power. Conversely, factor $k+1$: if exactly one distinct prime $p$, return $p$; else return $1$.

\subsection{Kummer-carry valuation}
Compute $\vp\!\bigl(\bin{a+b}{a}\bigr)$ by adding $a$ and $b$ in base $p$ and counting carries. For $n = p^a q$ the split $i = p^a$ has zero carries, certifying $p \nmid \bin{n}{i}$.

